(function(){var number=document.getElementById("lv-stock-number"),alert=document.getElementById("lv-stock-alert");if(!number||!alert)return;var initial=37,minimum=12,stepMs=15000,startedAt=Date.now(),reduceMotion=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches,lastValue=initial,timer;function currentValue(){return Math.max(minimum,initial-Math.floor((Date.now()-startedAt)/stepMs))}function render(){var next=currentValue();if(next===lastValue){if(next===minimum&&timer)clearInterval(timer);return}lastValue=next;if(reduceMotion){number.textContent=String(next)}else{alert.classList.add("is-updating");setTimeout(function(){number.textContent=String(next)},250);setTimeout(function(){alert.classList.remove("is-updating")},620)}if(next===minimum&&timer)clearInterval(timer)}timer=setInterval(render,500);document.addEventListener("visibilitychange",function(){if(!document.hidden)render()})})();